interface AutomationPlanProps {
    plan: Plan | null;
    sources: GroundingSource[];
    isLoading: boolean;
    refs: any;
    onSaveProject: () => void;
}

const Card: React.FC<{ 
    title: string; 
    content: string; 
    icon: React.ReactNode; 
    isLoading: boolean;
    idRef: React.RefObject<HTMLDivElement | null>;
}> = ({ title, content, icon, isLoading, idRef }) => {
    return (
        <div ref={idRef} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm">
            <div className="border-b border-gray-800 px-6 py-4 flex items-center justify-between bg-gray-800/20">
                <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                    <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg">{icon}</span>
                    {title}
                </h3>
                {isLoading && <LoadingSpinner />}
            </div>
            <div className="p-8">
                {content ? (
                    <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-p:leading-relaxed prose-li:text-gray-400 prose-strong:text-cyan-400">
                        {content.split('\n').map((paragraph, index) => {
                            if (paragraph.startsWith('- ') || paragraph.startsWith('* ')) {
                                return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="text-cyan-600">•</span> {paragraph.substring(2)}
                                </li>;
                            }
                            if (/^\d+\./.test(paragraph)) {
                                 return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="font-bold text-cyan-600">{paragraph.split('.')[0]}.</span> {paragraph.substring(paragraph.indexOf('.')+1)}
                                </li>;
                            }
                            return paragraph.trim() ? <p key={index} className="mb-4">{paragraph}</p> : null;
                        })}
                    </div>
                ) : (
                    <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                        <p className="text-sm italic">Pendiente de generación...</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export const AutomationPlan: React.FC<AutomationPlanProps> = ({ plan, sources, isLoading, refs, onSaveProject }) => {
    const handleExportPDF = () => {
        if (!plan) return;
        const doc = new jsPDF();
        let y = 20;
        const leftMargin = 20;
        const pageWidth = doc.internal.pageSize.width;
        const maxLineWidth = pageWidth - (leftMargin * 2);

        doc.setFontSize(22);
        doc.text("Plan de Automatización de Negocios", leftMargin, y);
        y += 15;

        const sections = [plan.analysis, plan.flows, plan.stack, plan.implementation, plan.roi];
        sections.forEach(section => {
            if (!section.title || !section.content) return;
            doc.setFontSize(16);
            doc.setTextColor(0, 100, 160);
            doc.text(section.title, leftMargin, y);
            y += 10;
            doc.setFontSize(11);
            doc.setTextColor(20, 20, 20);
            const lines = doc.splitTextToSize(section.content, maxLineWidth);
            lines.forEach((line: string) => {
                if (y > 280) { doc.addPage(); y = 20; }
                doc.text(line, leftMargin, y);
                y += 6;
            });
            y += 10;
        });

        doc.save("plan_automatizacion.pdf");
    };

    return (
        <div className="space-y-12">
            <div className="flex flex-col sm:flex-row justify-between items-center bg-gray-900/50 p-6 rounded-2xl border border-gray-800 gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-white">Resultados de Auditoría</h2>
                    <p className="text-gray-500 text-sm">Visualización en tiempo real de tu estrategia de automatización.</p>
                </div>
                <div className="flex gap-3">
                    <button 
                        onClick={onSaveProject}
                        disabled={!plan}
                        className="flex items-center px-5 py-2.5 bg-cyan-600/10 hover:bg-cyan-600/20 disabled:opacity-50 disabled:cursor-not-allowed text-cyan-400 rounded-xl transition-all border border-cyan-500/30 text-sm font-semibold"
                    >
                        <FloppyIcon className="w-5 h-5 mr-2" />
                        Guardar Proyecto
                    </button>
                    <button 
                        onClick={handleExportPDF}
                        disabled={!plan}
                        className="flex items-center px-5 py-2.5 bg-gray-800 hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl transition-all border border-gray-700 shadow-lg text-sm font-semibold"
                    >
                        <DocumentArrowDownIcon className="w-5 h-5 mr-2 text-gray-400" />
                        Exportar PDF
                    </button>
                </div>
            </div>

            <Card 
                idRef={refs.analysis}
                title="1. Análisis de Procesos Manuales" 
                content={plan?.analysis.content || ''} 
                icon={<AnalysisIcon />} 
                isLoading={isLoading && !plan}
            />

            <Card 
                idRef={refs.flows}
                title="2. Diseño de Flujos de Agentes" 
                content={plan?.flows.content || ''} 
                icon={<FlowIcon />} 
                isLoading={isLoading && !plan}
            />

            <Card 
                idRef={refs.stack}
                title="3. Stack Tecnológico Recomendado" 
                content={plan?.stack.content || ''} 
                icon={<StackIcon />} 
                isLoading={isLoading && !plan}
            />

            <Card 
                idRef={refs.implementation}
                title="4. Implementación Paso a Paso" 
                content={plan?.implementation.content || ''} 
                icon={<RocketIcon />} 
                isLoading={isLoading && !plan}
            />

            <Card 
                idRef={refs.roi}
                title="5. ROI Estimado" 
                content={plan?.roi.content || ''} 
                icon={<StatsIcon />} 
                isLoading={isLoading && !plan}
            />

            <div ref={refs.sources} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm">
                <div className="border-b border-gray-800 px-6 py-4 bg-gray-800/20">
                    <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                        <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg"><SearchIcon /></span>
                        Fuentes de Información
                    </h3>
                </div>
                <div className="p-8">
                    {sources.length > 0 ? (
                        <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {sources.map((source, index) => (
                                <li key={index} className="flex">
                                    <a 
                                        href={source.uri} 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="flex-1 p-4 bg-gray-900/50 border border-gray-800 rounded-xl hover:border-cyan-500/50 hover:bg-gray-800 transition-all group"
                                    >
                                        <p className="text-cyan-400 font-medium text-sm mb-1 group-hover:underline truncate">{source.title}</p>
                                        <p className="text-gray-500 text-xs truncate">{source.uri}</p>
                                    </a>
                                </li>
                            ))}
                        </ul>
                    ) : (
                        <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                            <p className="text-sm italic">Esperando búsqueda externa...</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Header } from './components/Header';
import { BusinessInput } from './components/BusinessInput';
import { AutomationPlan } from './components/AutomationPlan';
import { AdminPanel } from './components/AdminPanel';
import { ChatBot } from './components/ChatBot';
import { generateAutomationPlan } from './services/geminiService';
import type { Plan, GroundingSource, SavedPlan } from './types';

const STORAGE_KEY = 'automation_hub_database_v2';

const App: React.FC = () => {
    const [automationPlan, setAutomationPlan] = useState<Plan | null>(null);
    const [groundingSources, setGroundingSources] = useState<GroundingSource[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [isAdminOpen, setIsAdminOpen] = useState<boolean>(true);
    const [history, setHistory] = useState<SavedPlan[]>([]);
    const [currentDescription, setCurrentDescription] = useState<string>('');

    const sectionsRefs = {
        input: useRef<HTMLDivElement>(null),
        analysis: useRef<HTMLDivElement>(null),
        flows: useRef<HTMLDivElement>(null),
        stack: useRef<HTMLDivElement>(null),
        implementation: useRef<HTMLDivElement>(null),
        roi: useRef<HTMLDivElement>(null),
        sources: useRef<HTMLDivElement>(null),
    };

    // Cargar historial al iniciar
    useEffect(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            try {
                setHistory(JSON.parse(saved));
            } catch (e) {
                console.error("Error loading database", e);
            }
        }
    }, []);

    const saveToStorage = (newHistory: SavedPlan[]) => {
        setHistory(newHistory);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(newHistory));
    };

    const scrollToSection = (sectionId: keyof typeof sectionsRefs) => {
        sectionsRefs[sectionId].current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };

    const handleNewAudit = () => {
        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription('');
        scrollToSection('input');
    };

    const loadFromHistory = (savedPlan: SavedPlan) => {
        setAutomationPlan(savedPlan.plan);
        setGroundingSources(savedPlan.sources);
        setCurrentDescription(savedPlan.businessDescription);
        setTimeout(() => scrollToSection('analysis'), 100);
    };

    const handleDeleteProject = (id: string) => {
        if (window.confirm('¿Estás seguro de que deseas eliminar este proyecto de la base de datos?')) {
            const updatedHistory = history.filter(item => item.id !== id);
            saveToStorage(updatedHistory);
            // Si el proyecto borrado es el actual, limpiar la vista
            // Opcional: handleNewAudit(); 
        }
    };

    const handleSaveProject = () => {
        if (!automationPlan) return;

        const name = prompt("Asigna un nombre para guardar este proyecto en la Base de Datos:", "Proyecto Sin Nombre");
        if (!name) return;

        const savedItem: SavedPlan = {
            id: Date.now().toString(),
            name: name,
            timestamp: Date.now(),
            businessDescription: currentDescription,
            plan: automationPlan,
            sources: groundingSources
        };

        const updatedHistory = [savedItem, ...history];
        saveToStorage(updatedHistory);
        alert("Proyecto guardado exitosamente en la base de datos local.");
    };

    const handleImportProject = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target?.result as string;
                const importedPlan = JSON.parse(content) as SavedPlan;

                // Validación básica
                if (!importedPlan.plan || !importedPlan.id) {
                    throw new Error("Formato de archivo inválido");
                }

                // Evitar duplicados por ID, generar uno nuevo si colisiona
                const exists = history.some(h => h.id === importedPlan.id);
                if (exists) {
                    importedPlan.id = Date.now().toString() + Math.random().toString().slice(2, 5);
                    importedPlan.name = importedPlan.name + " (Importado)";
                }

                const updatedHistory = [importedPlan, ...history];
                saveToStorage(updatedHistory);
                loadFromHistory(importedPlan);
                alert("Proyecto importado correctamente.");
            } catch (err) {
                console.error("Error importing file:", err);
                alert("Error al importar el archivo. Asegúrate de que es un JSON válido generado por esta aplicación.");
            }
        };
        reader.readAsText(file);
    };

    const handleGeneratePlan = useCallback(async (businessDescription: string) => {
        if (!businessDescription.trim()) {
            setError("Por favor, describe tu negocio.");
            return;
        }
        setIsLoading(true);
        setError(null);
        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription(businessDescription);

        try {
            const result = await generateAutomationPlan(businessDescription);

            const sections = result.planText.split(/### \d+\.\s+.*?\n/);
            const contentSections = sections.filter(s => s.trim().length > 0);

            const newPlan: Plan = {
                analysis: { title: '1. Análisis de Procesos Manuales', content: contentSections[0] || '' },
                flows: { title: '2. Diseño de Flujos de Agentes', content: contentSections[1] || '' },
                stack: { title: '3. Stack Tecnológico Recomendado', content: contentSections[2] || '' },
                implementation: { title: '4. Implementación Paso a Paso', content: contentSections[3] || '' },
                roi: { title: '5. ROI Estimado', content: contentSections[4] || '' },
            };

            setAutomationPlan(newPlan);
            setGroundingSources(result.sources);

            // NOTA: Ya no guardamos automáticamente en el historial persistente.
            // El usuario debe hacer clic en "Guardar Proyecto".

        } catch (err) {
            console.error("Error generating plan:", err);
            setError("Hubo un error al generar el plan. Por favor, inténtalo de nuevo.");
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="h-screen bg-gray-950 text-gray-100 font-sans flex flex-col overflow-hidden">
            <Header onToggleAdmin={() => setIsAdminOpen(!isAdminOpen)} isAdminOpen={isAdminOpen} />

            <div className="flex flex-1 overflow-hidden relative">
                <AdminPanel 
                    isOpen={isAdminOpen} 
                    onNavigate={scrollToSection} 
                    hasPlan={!!automationPlan}
                    history={history}
                    onLoadPlan={loadFromHistory}
                    onNewAudit={handleNewAudit}
                    onImportProject={handleImportProject}
                    onDeleteProject={handleDeleteProject}
                />

                <main className="flex-1 overflow-y-auto bg-gray-900/30 p-4 md:p-8 space-y-12 pb-32 custom-scrollbar">
                    <div ref={sectionsRefs.input}>
                        <BusinessInput 
                            onGenerate={handleGeneratePlan} 
                            isLoading={isLoading} 
                            initialValue={currentDescription}
                        />
                    </div>

                    {error && (
                        <div className="bg-red-900/30 border border-red-800 text-red-200 px-6 py-4 rounded-xl text-center backdrop-blur-md">
                            {error}
                        </div>
                    )}

                    <AutomationPlan 
                        plan={automationPlan}
                        sources={groundingSources}
                        isLoading={isLoading}
                        refs={sectionsRefs}
                        onSaveProject={handleSaveProject}
                    />
                </main>
            </div>

            <ChatBot />
        </div>
    );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Header } from './components/Header';
import { BusinessInput } from './components/BusinessInput';
import { AutomationPlan } from './components/AutomationPlan';
import { AdminPanel } from './components/AdminPanel';
import { ChatBot } from './components/ChatBot';
import { generateAutomationPlan } from './services/geminiService';
import type { Plan, GroundingSource, SavedPlan, PlanSection } from './types';

const STORAGE_KEY = 'automation_hub_database_v2';

const App: React.FC = () => {
    const [automationPlan, setAutomationPlan] = useState<Plan | null>(null);
    const [groundingSources, setGroundingSources] = useState<GroundingSource[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [isAdminOpen, setIsAdminOpen] = useState<boolean>(true);
    const [history, setHistory] = useState<SavedPlan[]>([]);
    const [currentDescription, setCurrentDescription] = useState<string>('');
    const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);

    const sectionsRefs = {
        input: useRef<HTMLDivElement>(null),
        analysis: useRef<HTMLDivElement>(null),
        flows: useRef<HTMLDivElement>(null),
        stack: useRef<HTMLDivElement>(null),
        implementation: useRef<HTMLDivElement>(null),
        roi: useRef<HTMLDivElement>(null),
        sources: useRef<HTMLDivElement>(null),
    };

    // Cargar historial al iniciar
    useEffect(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            try {
                setHistory(JSON.parse(saved));
            } catch (e) {
                console.error("Error loading database", e);
            }
        }
    }, []);

    const saveToStorage = (newHistory: SavedPlan[]) => {
        try {
            setHistory(newHistory);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(newHistory));
        } catch (e) {
            console.error("Error saving to localStorage", e);
            alert("Error al guardar en el almacenamiento local (posiblemente lleno).");
        }
    };

    const scrollToSection = (sectionId: keyof typeof sectionsRefs) => {
        sectionsRefs[sectionId].current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };

    const handleNewAudit = () => {
        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription('');
        setCurrentProjectId(null); // Reset ID to create new
        scrollToSection('input');
    };

    const loadFromHistory = (savedPlan: SavedPlan) => {
        setAutomationPlan(savedPlan.plan);
        setGroundingSources(savedPlan.sources);
        setCurrentDescription(savedPlan.businessDescription);
        setCurrentProjectId(savedPlan.id); // Set active ID
        setTimeout(() => scrollToSection('analysis'), 100);
    };

    const handleDeleteProject = (id: string) => {
        if (window.confirm('¿Estás seguro de que deseas eliminar este proyecto de la base de datos?')) {
            const updatedHistory = history.filter(item => item.id !== id);
            saveToStorage(updatedHistory);
            if (currentProjectId === id) {
                handleNewAudit();
            }
        }
    };

    const handleSaveProject = () => {
        if (!automationPlan) return;

        if (currentProjectId) {
            // ACTUALIZAR PROYECTO EXISTENTE
            const updatedHistory = history.map(p => {
                if (p.id === currentProjectId) {
                    return {
                        ...p,
                        timestamp: Date.now(),
                        businessDescription: currentDescription,
                        plan: automationPlan,
                        sources: groundingSources
                    };
                }
                return p;
            });
            saveToStorage(updatedHistory);
            alert("Proyecto actualizado correctamente en la Base de Datos.");
        } else {
            // GUARDAR NUEVO PROYECTO
            let name = prompt("Asigna un nombre para guardar este proyecto:", "Nueva Auditoría");
            if (name === null) return; // User cancelled
            if (!name.trim()) name = "Sin Nombre";

            const newId = Date.now().toString();
            const savedItem: SavedPlan = {
                id: newId,
                name: name,
                timestamp: Date.now(),
                businessDescription: currentDescription,
                plan: automationPlan,
                sources: groundingSources
            };

            const updatedHistory = [savedItem, ...history];
            saveToStorage(updatedHistory);
            setCurrentProjectId(newId); // Switch to active mode
            alert("Proyecto nuevo guardado exitosamente.");
        }
    };

    const handleUpdatePlanSection = (sectionKey: keyof Plan, newContent: string) => {
        if (!automationPlan) return;
        setAutomationPlan({
            ...automationPlan,
            [sectionKey]: {
                ...automationPlan[sectionKey],
                content: newContent
            }
        });
    };

    const handleImportProject = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target?.result as string;
                const importedPlan = JSON.parse(content) as SavedPlan;

                if (!importedPlan.plan || !importedPlan.id) {
                    throw new Error("Formato de archivo inválido");
                }

                // Generar nuevo ID para evitar colisiones al importar
                importedPlan.id = Date.now().toString() + Math.random().toString().slice(2, 5);
                importedPlan.name = importedPlan.name + " (Importado)";

                const updatedHistory = [importedPlan, ...history];
                saveToStorage(updatedHistory);
                loadFromHistory(importedPlan);
                alert("Proyecto importado correctamente.");
            } catch (err) {
                console.error("Error importing file:", err);
                alert("Error al importar el archivo.");
            }
        };
        reader.readAsText(file);
    };

    const handleGeneratePlan = useCallback(async (businessDescription: string) => {
        if (!businessDescription.trim()) {
            setError("Por favor, describe tu negocio.");
            return;
        }
        setIsLoading(true);
        setError(null);
        // No borramos currentProjectId aquí para permitir "regenerar" sobre el mismo proyecto si se desea,
        // pero lo más limpio es tratar una generación como un borrador hasta que se guarda.
        // Mantenemos el ID si existe, asumiendo que el usuario quiere actualizar la versión actual.

        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription(businessDescription);

        try {
            const result = await generateAutomationPlan(businessDescription);

            const sections = result.planText.split(/### \d+\.\s+.*?\n/);
            const contentSections = sections.filter(s => s.trim().length > 0);

            const newPlan: Plan = {
                analysis: { title: '1. Análisis de Procesos Manuales', content: contentSections[0] || '' },
                flows: { title: '2. Diseño de Flujos de Agentes', content: contentSections[1] || '' },
                stack: { title: '3. Stack Tecnológico Recomendado', content: contentSections[2] || '' },
                implementation: { title: '4. Implementación Paso a Paso', content: contentSections[3] || '' },
                roi: { title: '5. ROI Estimado', content: contentSections[4] || '' },
            };

            setAutomationPlan(newPlan);
            setGroundingSources(result.sources);

        } catch (err) {
            console.error("Error generating plan:", err);
            setError("Hubo un error al generar el plan. Por favor, inténtalo de nuevo.");
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="h-screen bg-gray-950 text-gray-100 font-sans flex flex-col overflow-hidden">
            <Header onToggleAdmin={() => setIsAdminOpen(!isAdminOpen)} isAdminOpen={isAdminOpen} />

            <div className="flex flex-1 overflow-hidden relative">
                <AdminPanel 
                    isOpen={isAdminOpen} 
                    onNavigate={scrollToSection} 
                    hasPlan={!!automationPlan}
                    history={history}
                    onLoadPlan={loadFromHistory}
                    onNewAudit={handleNewAudit}
                    onImportProject={handleImportProject}
                    onDeleteProject={handleDeleteProject}
                    currentProjectId={currentProjectId}
                />

                <main className="flex-1 overflow-y-auto bg-gray-900/30 p-4 md:p-8 space-y-12 pb-32 custom-scrollbar">
                    <div ref={sectionsRefs.input}>
                        <BusinessInput 
                            onGenerate={handleGeneratePlan} 
                            isLoading={isLoading} 
                            initialValue={currentDescription}
                        />
                    </div>

                    {error && (
                        <div className="bg-red-900/30 border border-red-800 text-red-200 px-6 py-4 rounded-xl text-center backdrop-blur-md">
                            {error}
                        </div>
                    )}

                    <AutomationPlan 
                        plan={automationPlan}
                        sources={groundingSources}
                        isLoading={isLoading}
                        refs={sectionsRefs}
                        onSaveProject={handleSaveProject}
                        currentProjectId={currentProjectId}
                        onUpdateSection={handleUpdatePlanSection}
                    />
                </main>
            </div>

            <ChatBot />
        </div>
    );
};

export default App;

import React, { useState } from 'react';
import type { Plan, GroundingSource } from '../types';
import { LoadingSpinner } from './LoadingSpinner';
import { 
    AnalysisIcon, 
    FlowIcon, 
    StackIcon, 
    RocketIcon, 
    StatsIcon, 
    SearchIcon,
    DocumentArrowDownIcon,
    FloppyIcon,
    PencilIcon,
    CheckIcon
} from './icons';
import { jsPDF } from 'jspdf';

interface AutomationPlanProps {
    plan: Plan | null;
    sources: GroundingSource[];
    isLoading: boolean;
    refs: any;
    onSaveProject: () => void;
    currentProjectId: string | null;
    onUpdateSection: (sectionKey: keyof Plan, newContent: string) => void;
}

const Card: React.FC<{ 
    title: string; 
    content: string; 
    icon: React.ReactNode; 
    isLoading: boolean;
    idRef: React.RefObject<HTMLDivElement | null>;
    onSaveContent: (newContent: string) => void;
}> = ({ title, content, icon, isLoading, idRef, onSaveContent }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedContent, setEditedContent] = useState(content);

    // Sincronizar contenido si cambia externamente (ej: regeneración)
    React.useEffect(() => {
        setEditedContent(content);
    }, [content]);

    const handleSave = () => {
        onSaveContent(editedContent);
        setIsEditing(false);
    };

    return (
        <div ref={idRef} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm group hover:border-gray-700 transition-colors">
            <div className="border-b border-gray-800 px-6 py-4 flex items-center justify-between bg-gray-800/20">
                <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                    <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg">{icon}</span>
                    {title}
                </h3>
                <div className="flex items-center gap-2">
                    {isLoading && <LoadingSpinner />}
                    {!isLoading && content && (
                        <button
                            onClick={() => isEditing ? handleSave() : setIsEditing(true)}
                            className={`p-2 rounded-lg transition-all ${
                                isEditing 
                                ? 'bg-green-600/20 text-green-400 hover:bg-green-600/30' 
                                : 'bg-gray-800 text-gray-400 hover:text-white hover:bg-gray-700'
                            }`}
                            title={isEditing ? "Guardar cambios" : "Remodelar / Editar"}
                        >
                            {isEditing ? <CheckIcon className="w-4 h-4" /> : <PencilIcon className="w-4 h-4" />}
                        </button>
                    )}
                </div>
            </div>
            <div className="p-8">
                {isLoading && !content ? (
                     <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                        <p className="text-sm italic">Pendiente de generación...</p>
                    </div>
                ) : isEditing ? (
                    <textarea
                        value={editedContent}
                        onChange={(e) => setEditedContent(e.target.value)}
                        className="w-full h-96 bg-gray-900/50 border border-gray-700 rounded-xl p-4 text-gray-300 font-mono text-sm leading-relaxed focus:ring-2 focus:ring-cyan-500/30 outline-none resize-y"
                    />
                ) : content ? (
                    <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-p:leading-relaxed prose-li:text-gray-400 prose-strong:text-cyan-400">
                        {content.split('\n').map((paragraph, index) => {
                            if (paragraph.startsWith('- ') || paragraph.startsWith('* ')) {
                                return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="text-cyan-600">•</span> {paragraph.substring(2)}
                                </li>;
                            }
                            if (/^\d+\./.test(paragraph)) {
                                 return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="font-bold text-cyan-600">{paragraph.split('.')[0]}.</span> {paragraph.substring(paragraph.indexOf('.')+1)}
                                </li>;
                            }
                            return paragraph.trim() ? <p key={index} className="mb-4">{paragraph}</p> : null;
                        })}
                    </div>
                ) : (
                    <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                        <p className="text-sm italic">Esperando datos...</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export const AutomationPlan: React.FC<AutomationPlanProps> = ({ 
    plan, 
    sources, 
    isLoading, 
    refs, 
    onSaveProject, 
    currentProjectId,
    onUpdateSection 
}) => {
    const handleExportPDF = () => {
        if (!plan) return;
        const doc = new jsPDF();
        let y = 20;
        const leftMargin = 20;
        const pageWidth = doc.internal.pageSize.width;
        const maxLineWidth = pageWidth - (leftMargin * 2);

        doc.setFontSize(22);
        doc.text("Plan de Automatización", leftMargin, y);
        y += 15;

        const sections = [plan.analysis, plan.flows, plan.stack, plan.implementation, plan.roi];
        sections.forEach(section => {
            if (!section.title || !section.content) return;
            doc.setFontSize(16);
            doc.setTextColor(0, 100, 160);
            doc.text(section.title, leftMargin, y);
            y += 10;
            doc.setFontSize(11);
            doc.setTextColor(20, 20, 20);
            const lines = doc.splitTextToSize(section.content, maxLineWidth);
            lines.forEach((line: string) => {
                if (y > 280) { doc.addPage(); y = 20; }
                doc.text(line, leftMargin, y);
                y += 6;
            });
            y += 10;
        });

        doc.save("plan_automatizacion.pdf");
    };

    return (
        <div className="space-y-12">
            <div className="flex flex-col sm:flex-row justify-between items-center bg-gray-900/50 p-6 rounded-2xl border border-gray-800 gap-4 sticky top-16 z-10 backdrop-blur-md shadow-lg">
                <div>
                    <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                        Resultados de Auditoría
                        {currentProjectId && <span className="text-xs px-2 py-1 bg-green-500/20 text-green-400 rounded-full border border-green-500/30">Modo Edición</span>}
                    </h2>
                    <p className="text-gray-500 text-sm">Visualiza, remodela y exporta tu estrategia.</p>
                </div>
                <div className="flex gap-3">
                    <button 
                        onClick={onSaveProject}
                        disabled={!plan}
                        className={`flex items-center px-5 py-2.5 rounded-xl transition-all border text-sm font-bold shadow-lg ${
                            currentProjectId 
                            ? 'bg-green-600 hover:bg-green-500 text-white border-green-500' 
                            : 'bg-cyan-600 hover:bg-cyan-500 text-white border-cyan-500'
                        } disabled:opacity-50 disabled:cursor-not-allowed disabled:bg-gray-800 disabled:border-gray-700 disabled:text-gray-500`}
                    >
                        <FloppyIcon className="w-5 h-5 mr-2" />
                        {currentProjectId ? 'Actualizar Proyecto' : 'Guardar Proyecto'}
                    </button>
                    <button 
                        onClick={handleExportPDF}
                        disabled={!plan}
                        className="flex items-center px-5 py-2.5 bg-gray-800 hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl transition-all border border-gray-700 shadow-lg text-sm font-semibold"
                    >
                        <DocumentArrowDownIcon className="w-5 h-5 mr-2 text-gray-400" />
                        Exportar PDF
                    </button>
                </div>
            </div>

            <Card 
                idRef={refs.analysis}
                title="1. Análisis de Procesos Manuales" 
                content={plan?.analysis.content || ''} 
                icon={<AnalysisIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('analysis', c)}
            />

            <Card 
                idRef={refs.flows}
                title="2. Diseño de Flujos de Agentes" 
                content={plan?.flows.content || ''} 
                icon={<FlowIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('flows', c)}
            />

            <Card 
                idRef={refs.stack}
                title="3. Stack Tecnológico Recomendado" 
                content={plan?.stack.content || ''} 
                icon={<StackIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('stack', c)}
            />

            <Card 
                idRef={refs.implementation}
                title="4. Implementación Paso a Paso" 
                content={plan?.implementation.content || ''} 
                icon={<RocketIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('implementation', c)}
            />

            <Card 
                idRef={refs.roi}
                title="5. ROI Estimado" 
                content={plan?.roi.content || ''} 
                icon={<StatsIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('roi', c)}
            />

            <div ref={refs.sources} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm">
                <div className="border-b border-gray-800 px-6 py-4 bg-gray-800/20">
                    <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                        <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg"><SearchIcon /></span>
                        Fuentes de Información
                    </h3>
                </div>
                <div className="p-8">
                    {sources.length > 0 ? (
                        <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {sources.map((source, index) => (
                                <li key={index} className="flex">
                                    <a 
                                        href={source.uri} 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="flex-1 p-4 bg-gray-900/50 border border-gray-800 rounded-xl hover:border-cyan-500/50 hover:bg-gray-800 transition-all group"
                                    >
                                        <p className="text-cyan-400 font-medium text-sm mb-1 group-hover:underline truncate">{source.title}</p>
                                        <p className="text-gray-500 text-xs truncate">{source.uri}</p>
                                    </a>
                                </li>
                            ))}
                        </ul>
                    ) : (
                        <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                            <p className="text-sm italic">Esperando búsqueda externa...</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useRef } from 'react';
import { 
    LayoutIcon, 
    AnalysisIcon, 
    FlowIcon, 
    StackIcon, 
    RocketIcon, 
    StatsIcon, 
    SearchIcon,
    SparklesIcon,
    HistoryIcon,
    UploadIcon,
    TrashIcon,
    DownloadIcon
} from './icons';
import type { SavedPlan } from '../types';

interface AdminPanelProps {
    isOpen: boolean;
    onNavigate: (sectionId: any) => void;
    hasPlan: boolean;
    history: SavedPlan[];
    onLoadPlan: (plan: SavedPlan) => void;
    onNewAudit: () => void;
    onImportProject: (file: File) => void;
    onDeleteProject: (id: string) => void;
    currentProjectId: string | null;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
    isOpen, 
    onNavigate, 
    hasPlan, 
    history, 
    onLoadPlan, 
    onNewAudit,
    onImportProject,
    onDeleteProject,
    currentProjectId
}) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const navItems = [
        { id: 'input', label: 'Describe tu Negocio', icon: <LayoutIcon /> },
        { id: 'analysis', label: 'Análisis de Procesos', icon: <AnalysisIcon /> },
        { id: 'flows', label: 'Diseño de Flujos', icon: <FlowIcon /> },
        { id: 'stack', label: 'Stack Tecnológico', icon: <StackIcon /> },
        { id: 'implementation', label: 'Implementación', icon: <RocketIcon /> },
        { id: 'roi', label: 'ROI Estimado', icon: <StatsIcon /> },
        { id: 'sources', label: 'Fuentes de Datos', icon: <SearchIcon /> },
    ];

    const formatDate = (timestamp: number) => {
        return new Intl.DateTimeFormat('es-ES', { 
            day: '2-digit', 
            month: 'short', 
            hour: '2-digit', 
            minute: '2-digit' 
        }).format(new Date(timestamp));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            onImportProject(e.target.files[0]);
            e.target.value = '';
        }
    };

    const handleDownload = (e: React.MouseEvent, plan: SavedPlan) => {
        e.stopPropagation();
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(plan));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", `${plan.name.replace(/\s+/g, '_')}_${plan.id}.json`);
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    };

    return (
        <aside 
            className={`bg-gray-900 border-r border-gray-800 transition-all duration-300 ease-in-out flex-shrink-0 z-20 overflow-hidden flex flex-col ${
                isOpen ? 'w-64' : 'w-0'
            }`}
        >
            <div className="w-64 p-6 flex flex-col h-full overflow-hidden">
                <div className="mb-6">
                    <button
                        onClick={onNewAudit}
                        className="w-full flex items-center justify-center gap-2 py-3 bg-cyan-600/10 hover:bg-cyan-600/20 text-cyan-400 border border-cyan-500/30 rounded-xl text-sm font-bold transition-all mb-6 group"
                    >
                        <SparklesIcon className="w-4 h-4 group-hover:rotate-12" />
                        Nueva Auditoría
                    </button>

                    <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-widest mb-4">Navegación</h2>
                    <nav className="space-y-1">
                        {navItems.map((item) => (
                            <button
                                key={item.id}
                                onClick={() => onNavigate(item.id)}
                                className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium text-gray-400 hover:text-cyan-400 hover:bg-gray-800/50 transition-all group"
                            >
                                <span className="text-gray-500 group-hover:text-cyan-400 transition-colors">
                                    {React.cloneElement(item.icon as React.ReactElement, { className: 'w-4 h-4' })}
                                </span>
                                {item.label}
                            </button>
                        ))}
                    </nav>
                </div>

                <div className="flex-1 overflow-hidden flex flex-col border-t border-gray-800 pt-6">
                    <div className="flex items-center justify-between mb-4">
                        <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                            <HistoryIcon className="w-3 h-3" />
                            Base de Datos
                        </h2>
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-cyan-400 hover:text-white p-1 rounded hover:bg-gray-800 transition-colors"
                            title="Importar Proyecto (JSON)"
                        >
                            <UploadIcon className="w-4 h-4" />
                        </button>
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            className="hidden" 
                            accept=".json" 
                            onChange={handleFileChange}
                        />
                    </div>

                    <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-2">
                        {history.length > 0 ? (
                            history.map((item) => (
                                <div
                                    key={item.id}
                                    className={`w-full p-3 rounded-xl border transition-all group relative ${
                                        currentProjectId === item.id 
                                        ? 'bg-cyan-900/20 border-cyan-500/50 shadow-[0_0_10px_rgba(6,182,212,0.1)]' 
                                        : 'bg-gray-800/30 border-gray-800 hover:border-gray-700 hover:bg-gray-800/50'
                                    }`}
                                >
                                    <button 
                                        onClick={() => onLoadPlan(item)}
                                        className="text-left w-full"
                                    >
                                        <div className="text-[10px] text-gray-500 mb-1 font-mono uppercase tracking-tighter flex justify-between">
                                            <span>{formatDate(item.timestamp)}</span>
                                            {currentProjectId === item.id && <span className="text-cyan-400 font-bold">ACTIVO</span>}
                                        </div>
                                        <div className={`text-xs font-medium line-clamp-2 leading-relaxed transition-colors pr-8 ${
                                            currentProjectId === item.id ? 'text-cyan-300' : 'text-gray-300 group-hover:text-cyan-400'
                                        }`}>
                                            {item.name || item.businessDescription}
                                        </div>
                                    </button>

                                    <div className="absolute top-2 right-2 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDeleteProject(item.id); }}
                                            className="text-red-400 hover:text-red-300 p-1 hover:bg-red-900/30 rounded"
                                            title="Eliminar"
                                        >
                                            <TrashIcon className="w-3 h-3" />
                                        </button>
                                         <button 
                                            onClick={(e) => handleDownload(e, item)}
                                            className="text-gray-400 hover:text-white p-1 hover:bg-gray-700 rounded"
                                            title="Descargar JSON"
                                        >
                                            <DownloadIcon className="w-3 h-3" />
                                        </button>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="text-[11px] text-gray-600 italic py-4 text-center border-2 border-dashed border-gray-800 rounded-xl">
                                Base de datos vacía
                            </div>
                        )}
                    </div>
                </div>

                <div className="mt-6">
                    <div className="bg-gray-800/50 rounded-xl p-4 border border-gray-700">
                        <div className="text-xs text-gray-500 mb-2">Estado del Plan</div>
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${hasPlan ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-yellow-500 animate-pulse'}`}></div>
                            <span className="text-xs font-medium">{hasPlan ? (currentProjectId ? 'Guardado' : 'Borrador') : 'Inactivo'}</span>
                        </div>
                    </div>
                </div>
            </div>
        </aside>
    );
};

